/* Interface between the recompiled game code (the files in port/gen, generated by
 * tools/recomp/recomp.py) and the runtime (port/src/).
 *
 * The game's registers live in g_cpu; RAM and scratchpad are plain arrays.
 * Loads and stores to RAM are inline; anything else (hardware registers)
 * goes to the runtime's I/O handlers. */
#ifndef RECOMP_H
#define RECOMP_H

#include <stdint.h>
#include <string.h>

typedef struct {
    uint32_t r[32];
    uint32_t hi, lo;
} Cpu;

extern Cpu g_cpu;
#define R  g_cpu.r
#define HI g_cpu.hi
#define LO g_cpu.lo

#define RAM_SIZE     0x200000
#define SCRATCH_SIZE 0x400
extern uint8_t g_ram[RAM_SIZE];
extern uint8_t g_scratch[SCRATCH_SIZE];

/* Hardware registers, scratchpad, BIOS area and anything else. */
uint32_t mem_slow_r32(uint32_t a);
uint32_t mem_slow_r16(uint32_t a);
uint32_t mem_slow_r8(uint32_t a);
void mem_slow_w32(uint32_t a, uint32_t v);
void mem_slow_w16(uint32_t a, uint32_t v);
void mem_slow_w8(uint32_t a, uint32_t v);

/* Main RAM is mirrored through the first 8 MB of KUSEG/KSEG0/KSEG1. */
#define RAM_PHYS(a) ((a) & 0x1FFFFFFFu)
#define IS_RAM(p)   ((p) < 0x800000u)

static inline uint32_t MEM_R32(uint32_t a) {
    uint32_t p = RAM_PHYS(a);
    if (IS_RAM(p)) { uint32_t v; memcpy(&v, g_ram + (p & 0x1FFFFC), 4); return v; }
    return mem_slow_r32(a);
}
static inline uint32_t MEM_R16(uint32_t a) {
    uint32_t p = RAM_PHYS(a);
    if (IS_RAM(p)) { uint16_t v; memcpy(&v, g_ram + (p & 0x1FFFFE), 2); return v; }
    return mem_slow_r16(a);
}
static inline uint32_t MEM_R8(uint32_t a) {
    uint32_t p = RAM_PHYS(a);
    if (IS_RAM(p)) return g_ram[p & 0x1FFFFF];
    return mem_slow_r8(a);
}
#ifdef RT_WATCH_WRITES
void rt_watch_write(uint32_t a, uint32_t v, int size);   /* debug builds: logs writes to RT_WATCHW */
extern uint32_t g_watch_lo, g_watch_hi;
#define WATCH(a, v, n) do { uint32_t q_ = RAM_PHYS(a); if (q_ >= g_watch_lo && q_ < g_watch_hi) rt_watch_write(a, v, n); } while (0)
#else
#define WATCH(a, v, n) ((void)0)
#endif
static inline void MEM_W32(uint32_t a, uint32_t v) {
    WATCH(a, v, 4);
    uint32_t p = RAM_PHYS(a);
    if (IS_RAM(p)) { memcpy(g_ram + (p & 0x1FFFFC), &v, 4); return; }
    mem_slow_w32(a, v);
}
static inline void MEM_W16(uint32_t a, uint32_t v) {
    WATCH(a, v, 2);
    uint32_t p = RAM_PHYS(a);
    if (IS_RAM(p)) { uint16_t h = (uint16_t)v; memcpy(g_ram + (p & 0x1FFFFE), &h, 2); return; }
    mem_slow_w16(a, v);
}
static inline void MEM_W8(uint32_t a, uint32_t v) {
    WATCH(a, v, 1);
    uint32_t p = RAM_PHYS(a);
    if (IS_RAM(p)) { g_ram[p & 0x1FFFFF] = (uint8_t)v; return; }
    mem_slow_w8(a, v);
}

uint32_t rt_lwl(uint32_t old, uint32_t addr);
uint32_t rt_lwr(uint32_t old, uint32_t addr);
void rt_swl(uint32_t addr, uint32_t v);
void rt_swr(uint32_t addr, uint32_t v);
void rt_div(uint32_t a, uint32_t b);
void rt_divu(uint32_t a, uint32_t b);

/* Calls through a pointer, into an overlay slot, or into the BIOS. */
void rt_call(uint32_t addr);
void rt_badjump(uint32_t pc, uint32_t target);
void rt_syscall(uint32_t pc);
void rt_break(uint32_t pc, uint32_t code);

uint32_t rt_mfc0(int reg);
void rt_mtc0(int reg, uint32_t v);
void rt_rfe(void);

/* GTE (COP2) */
uint32_t gte_read_data(int reg);
uint32_t gte_read_ctrl(int reg);
void gte_write_data(int reg, uint32_t v);
void gte_write_ctrl(int reg, uint32_t v);
void gte_command(uint32_t cmd);
void gte_swc2(uint32_t addr, int reg);   /* store a GTE data register to memory */

/* Time: every backward branch spends a little of the budget; when it runs
 * out the runtime advances the hardware clock and runs pending interrupts,
 * so the game's wait loops see time pass. */
extern int32_t g_rt_budget;
extern uint32_t g_poll_pc;      /* address of the last loop that polled */
void rt_poll(void);
#define RT_POLL_AT(pc) do { if (--g_rt_budget <= 0) { g_poll_pc = (pc); rt_poll(); } } while (0)
/* A poll a saved game can't continue from (bit 1 set in g_poll_pc). */
#define RT_POLL_NOSAVE(pc) do { if (--g_rt_budget <= 0) { g_poll_pc = (pc) | 2u; rt_poll(); } } while (0)
/* Resuming a saved game (savestate.c): the address the next translated
 * function called should continue at (a call's return address, or a poll's
 * address | 1); g_resume_miss is set if it isn't one of its own. */
extern uint32_t g_resume_pc;
extern int g_resume_miss;

typedef void (*RtFn)(void);
/* A function for the interpreter (port/src/interp.c; tables written by
 * tools/recomp/meta.py): its instructions are the address ranges
 * rng[r_off .. r_off + r_n), how its j and jr were translated are the
 * (pc, code) pairs ann[a_off .. a_off + a_n). */
typedef struct {
    uint32_t entry;
    uint32_t r_off, r_n, a_off, a_n;
    uint32_t flags;     /* IN_DELAY_LABELS: some jump lands in a delay slot */
    RtFn hook;      /* tools/recomp/hooks.txt */
} InFunc;
#define IN_DELAY_LABELS 1
typedef struct {
    uint32_t addr;
    RtFn fn;        /* what calls run: the translation, or the native C */
    RtFn resume;    /* what a save state continues in: always the translation
                     * (a native can't be re-entered in the middle, and a save
                     * state made before a function was decompiled can have
                     * it on its call chain) */
    const InFunc *meta;     /* interpreter build: fn/resume are 0 unless native */
} RtFunc;
typedef struct {
    const char *name;
    uint32_t vram, code_lo, code_hi;
    const uint8_t *sig;
    uint32_t sig_len;
    const RtFunc *funcs;
    uint32_t nfuncs;
    /* interpreter build (sig is 0 there): */
    uint64_t sig_hash;          /* FNV-1a of the sig_len bytes at vram */
    const uint32_t *rng, *ann, *jt;
    const uint32_t *patch;      /* runs of (address, count, words...) */
    uint32_t npatch;
} RtModule;
void interp_call(const RtModule *m, const RtFunc *f);
void interp_resume(const RtModule *m, const RtFunc *f);
extern const RtModule rt_modules[];
extern const int rt_module_count;

#endif
